{"op":"define","frontend":"flow","source":"word customer::renewal-savings(customer: Customer, subscription: Subscription) -> Float {
    effects none
    let originalBalance = customer::balance(customer)
    let premiumFactor = if ::equals(customer::kind(customer), "premium") { 0.9 } else { 1.0 }
    let afterPremium = float::multiply(originalBalance, premiumFactor)
    let annualAndRenewable = bool::and(::equals(subscription::term(subscription), "annual"), subscription::renewable(subscription))
    let annualFactor = if annualAndRenewable { 0.95 } else { 1.0 }
    let renewalBalance = float::multiply(afterPremium, annualFactor)
    float::subtract(originalBalance, renewalBalance)
}
test customer::renewal-savings/combined {
    customer::renewal-savings(customer::new("premium", 100.0), subscription::new("annual", true)) => 14.5
}
test customer::renewal-savings/premium-only {
    customer::renewal-savings(customer::new("premium", 100.0), subscription::new("monthly", true)) => 10.0
}
test customer::renewal-savings/annual-only {
    customer::renewal-savings(customer::new("standard", 100.0), subscription::new("annual", true)) => 5.0
}
test customer::renewal-savings/not-renewable {
    customer::renewal-savings(customer::new("premium", 100.0), subscription::new("annual", false)) => 10.0
}
test customer::renewal-savings/case-sensitive {
    customer::renewal-savings(customer::new("Premium", 100.0), subscription::new("Annual", true)) => 0.0
}"}

